import type { ClientBatch } from "./runtime.ts";

/** Identifies only canonical bunch IDs generated by this client for this path. */
export function localBunchSeq(
  bunchId: string,
  clientId: string,
  path: string
): number | undefined {
  let parts: unknown;
  try {
    parts = JSON.parse(bunchId);
  } catch {
    return undefined;
  }
  if (
    !Array.isArray(parts) ||
    parts.length !== 3 ||
    parts[0] !== clientId ||
    parts[1] !== path ||
    !Number.isSafeInteger(parts[2]) ||
    parts[2] < 1 ||
    JSON.stringify(parts) !== bunchId
  ) {
    return undefined;
  }
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- Number.isSafeInteger and bounds above validate this parsed allocation counter.
  return parts[2] as number;
}

/**
 * Checks a typed incoming batch against an application-authenticated writer ID.
 * Only new insertion IDs are checked, not anchors or deletion targets.
 * Decode unknown wire input first; this opt-in check does not authenticate writers.
 */
export function assertClientBatchNamespace(
  batch: ClientBatch,
  expectedClientId: string
): void {
  if (typeof expectedClientId !== "string" || expectedClientId.length === 0) {
    throw new TypeError("expectedClientId must be a non-empty authenticated writer ID");
  }
  if (batch.clientId !== expectedClientId) {
    throw new TypeError("Invalid batch /clientId: does not match the authenticated writer ID");
  }
  for (const [index, operation] of batch.operations.entries()) {
    if (operation.type !== "list/insert" && operation.type !== "text/insert") continue;
    if (localBunchSeq(operation.id.bunchId, expectedClientId, operation.path) === undefined) {
      throw new TypeError(`Invalid batch /operations/${index}/id/bunchId: expected this writer's canonical namespace for ${operation.path}`);
    }
  }
}
